import {VERSION,defaultWorkspace,validateWorkspace,migrateWorkspace,specs,generateAmortizationSchedule,evaluateScenario,evaluateBankStatementIntegrity,calculateSpread,qualitativeScore,indicativeDebtCap,validateBank,validateSpreads,suggestedAuditHaircut} from './underwriting-model.js';
import {parseCSV} from './model.js';
const $=s=>document.querySelector(s),h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=0)=>Number.isFinite(v)?(v<0?'('+Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d})+')':v.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d})):'N/A';
const rp=v=>Number.isFinite(v)?v<0?'(Rp'+fmt(Math.abs(v))+')':'Rp'+fmt(v):'N/A',ratio=v=>Number.isFinite(v)?fmt(v,2)+'×':'N/A',percent=v=>Number.isFinite(v)?fmt(v*100,1)+'%':'N/A';
const keys=['REQUESTED','PROPOSED_CAP','DOWNSIDE'];
export const institutionNav=[['deal','Deal structuring'],['recon','Bank reconciliation'],['spread','Historical spreads'],['governance','Group & contract risk'],['proposal','Committee proposal']];
let w=defaultWorkspace(),hooks={},db=null,loadMessage='',saveTimer=null,storageError='';
function getPath(o,path){return path.split('.').reduce((a,k)=>a?.[k],o);}function setPath(o,path,value){const parts=path.split('.'),last=parts.pop();parts.reduce((a,k)=>a[k],o)[last]=value;}
export function institutionSnapshot(){return structuredClone(w);}
export function restoreInstitution(raw){const validated=migrateWorkspace(raw);w=validated;persist('Workspace imported');}
export async function initializeInstitution(options){hooks=options;try{const saved=localStorage.getItem('credit-institution-v2');if(saved)w=migrateWorkspace(JSON.parse(saved));}catch(err){loadMessage='Saved institutional data could not be loaded: '+err.message+'. The original storage has been retained; download it before replacement.';}
try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('credit-workbench-institution',1);r.onupgradeneeded=()=>r.result.createObjectStore('workspace');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});if(!localStorage.getItem('credit-institution-v2')){const saved=await new Promise((resolve,reject)=>{const r=db.transaction('workspace').objectStore('workspace').get('active');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});if(saved)w=migrateWorkspace(saved);}}catch{storageError='IndexedDB unavailable; browser storage fallback is active.';}validateWorkspace(w);bindEvents();}
function persist(action='Inputs updated'){w.lastSaved=new Date().toISOString();w.auditLog.push({at:w.lastSaved,action});w.auditLog=w.auditLog.slice(-1000);clearTimeout(saveTimer);saveTimer=setTimeout(()=>{const snapshot=JSON.stringify(w);try{localStorage.setItem('credit-institution-v2',snapshot);}catch{storageError='Browser storage full or unavailable. Export a backup now.';hooks.toast(storageError);}if(db){try{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(structuredClone(w),'active');tx.onerror=()=>hooks.toast('IndexedDB save failed; export a backup.');}catch{hooks.toast('IndexedDB save unavailable; export a backup.');}}const s=$('#institution-save');if(s)s.textContent='Saved locally · '+new Date(w.lastSaved).toLocaleTimeString('en-GB',{timeZone:'Asia/Jakarta'});},250);}
function input(path,label,opts={}){const value=getPath(w,path),parts=path.split('.'),key=parts.at(-1),schema=opts.schema||specs[opts.group||parts[0]]||{},range=schema[key]||[];return `<label>${h(label)}${opts.select?`<select data-inst="${path}" aria-label="${h(label)}">${opts.select.map(v=>`<option value="${h(v)}" ${value===v?'selected':''}>${h(opts.labels?.[v]||v.replaceAll('_',' '))}</option>`).join('')}</select>`:opts.checkbox?`<span class="checkbox-label"><input type="checkbox" data-inst="${path}" ${value?'checked':''}>${h(opts.detail||'Confirmed')}</span>`:opts.textarea?`<textarea data-inst="${path}" aria-label="${h(label)}">${h(value)}</textarea>`:`<input data-inst="${path}" aria-label="${h(label)}" type="${opts.type||'number'}" value="${h(value??'')}" ${opts.type==='text'||opts.type==='date'?'':`step="${range[2]?1:'any'}" ${range.length?`min="${range[0]}" max="${range[1]}"`:''}`}>`}${opts.note?`<small class="field-note">${h(opts.note)}</small>`:''}</label>`;}
const fields=(group,rows,defaults={})=>rows.map(([key,label,opts={}])=>input(`${group}.${key}`,label,{...defaults,...opts,group})).join('');
function panel(title,body,sub=''){return `<section class="card padded institution-panel"><h2>${title}</h2>${sub?`<p class="card-subtitle">${sub}</p>`:''}${body}</section>`;}
function header(title,sub){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions"><button class="btn" data-inst-action="backup">Export workspace</button><button class="btn" data-inst-action="load">Load workspace</button><button class="btn" data-inst-action="density">${w.ui.compact?'Comfortable':'Compact'} view</button></div></div><div class="institution-context"><strong>${h(w.borrower.companyName)}</strong><span>IDR · ${h(w.source)}</span><span id="institution-save">${w.lastSaved?'Saved locally':'Illustrative case · unsaved'}</span></div>${loadMessage?`<div class="banner amber">${h(loadMessage)} <button class="text-button" data-inst-action="recover">Download stored source</button></div>`:''}${storageError?`<p class="evidence">${h(storageError)}</p>`:''}<div id="institution-ceiling" class="banner breach-banner" ${evaluateScenario(w,'PROPOSED_CAP').ceilingBreach?'':'hidden'}>CRITICAL: Proposed exposure exceeds the entered lender group ceiling.</div><div id="institution-error" role="alert"></div><input id="institution-file" type="file" accept=".json" hidden>`;}
export function institutionView(route){document.body.classList.toggle('compact',w.ui.compact);const body={deal:dealView,recon:reconView,spread:spreadView,governance:governanceView,proposal:proposalView}[route];return `<div class="institution" data-institution-route="${route}">${body()}</div>`;}
function decisionMatrix(){const results=keys.map(k=>evaluateScenario(w,k));const cells=[['Facility amount',r=>rp(r.amount)],['Equity contribution',r=>rp(r.equityContribution)],['Financing / asset cost',r=>percent(r.amount/(w.equipmentDeal.numberOfUnits*w.equipmentDeal.unitCost))],['Utilization',r=>percent(r.scenario.utilizationPct)],['Annual PPh 23 withheld',r=>rp(r.bridge.pph23WithholdingDeduction*12)],['Annual CFADS',r=>auditButton(r.key,'cfads',rp(r.bridge.annualizedCFADS))],['Year-1 global debt service',r=>auditButton(r.key,'service',rp(r.annualDebtServiceYear1))],['Steady-state DSCR',r=>auditButton(r.key,'dscr',ratio(r.steadyStateDSCR))],['Year-1 DSCR after DSO',r=>auditButton(r.key,'year1',ratio(r.year1PostShockDSCR))],['DSCR covenant headroom',r=>r.year1PostShockDSCR===null?'N/A (no debt service)':ratio(r.year1PostShockDSCR-w.policy.minimumDSCR)],['Break-even utilization',r=>auditButton(r.key,'breakeven',r.breakEven.value===null?r.breakEven.status.replaceAll('_',' '):percent(r.breakEven.value)+(r.breakEven.value>1?' · infeasible':''))],['DSO cash drag',r=>rp(r.workingCapitalDSODrag)],['Undrawn / confirmed KMK',r=>rp(r.existing.undrawnKMKHeadroom)+' / '+rp(r.existing.confirmedKMKHeadroom)],['DSRA required',r=>rp(r.debtServiceReserveRequired)],['Net liquidity headroom',r=>rp(r.netLiquidityHeadroom)],['Lender group ceiling use',r=>percent(r.groupBMPKUtilization)],['Net recovery at inception',r=>rp(r.collateral[0].netForcedSaleValue)],['Gross appraised coverage',r=>percent(r.amount>0?w.equipmentDeal.assetMarketValueNew/r.amount:null)],['Net collateral coverage',r=>percent(r.collateral[0].netCoverage)],['Contract vs loan tenor',r=>r.contractMatch?'Tenor matched':'Tenor mismatch'],['Screening outcome',r=>r.status]];return `<div class="table-scroll"><table class="decision-table"><thead><tr><th>Underwriting check</th>${results.map(r=>`<th>${h(r.scenario.name)}<small>${r.key==='REQUESTED'?'Borrower request':r.key==='PROPOSED_CAP'?'Underwriter structure':'Stressed proposed facility'}</small></th>`).join('')}</tr></thead><tbody>${cells.map(([label,fn])=>`<tr><th scope="row">${label}</th>${results.map(r=>`<td class="${label.includes('DSCR')&&r.year1PostShockDSCR!==null&&r.year1PostShockDSCR<w.policy.minimumDSCR||label==='Net liquidity headroom'&&r.netLiquidityHeadroom<0||label==='Lender group ceiling use'&&r.ceilingBreach?'breach-cell':''}">${fn(r)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="evidence">CFADS is a projected project contribution; existing facility service is included. Confirm that the project cash is legally available to service those facilities. Borrowing liquidity is not counted as CFADS. No automated approval is issued.</p>`;}
function auditButton(key,type,text){return `<button class="audit-value" data-inst-audit="${key}:${type}" title="Show formula and populated inputs">${text}</button>`;}
function dealView(){return header('Equipment underwriting','Structure the deal, test repayment, and compare the downside.')+`<div id="institution-results">${dealResults()}</div><div class="institution-tabs"><button data-inst-tab="deal-inputs" class="btn primary">Deal inputs</button><button data-inst-tab="scenario-inputs" class="btn">Scenario controls</button><button data-inst-tab="facility-inputs" class="btn">Existing facilities</button></div><div id="deal-inputs" class="institution-tab"><div class="detail-grid">${panel('Facility & repayment',`<div class="fields">${fields('equipmentDeal',[['numberOfUnits','Equipment units'],['unitCost','Cost per unit (IDR)'],['requestedFinancingPct','Requested financing (decimal)'],['proposedCapFinancingPct','Proposed financing (decimal)'],['tenorMonths','Total tenor (months)'],['annualInterestRate','Annual interest (decimal)'],['repaymentStructure','Repayment method',{select:['ANNUITY','EQUAL_PRINCIPAL']}],['gracePeriodMonths','Interest-only grace (months)'],['debtServiceReserveMonths','DSRA months'],['unrestrictedCashAvailable','Unrestricted cash (IDR)']])}</div>`,'All rates use decimals. Grace is included in the total tenor.')}${panel('Operating cash bridge',`<div class="fields">${fields('equipmentDeal',[['plannedHoursPerMonthPerUnit','Capacity hours / unit / month'],['billingTariffPerHour','Hourly billing tariff (IDR)'],['fuelConsumptionLitersPerHour','Fuel liters / operating hour'],['fuelPricePerLiter','Fuel price / liter (IDR)'],['fuelPassThroughPct','Fuel cost passed through (decimal)'],['operatorCostPerUnitMonth','Operator cash cost / unit / month'],['maintenanceReservePerUnitMonth','Maintenance capex reserve / unit / month'],['sgAndAAllocationPerUnitMonth','Overhead / unit / month'],['pph23WithholdingRate','PPh 23 withholding (decimal)'],['cashTaxRate','Cash-tax proxy (decimal)'],['withholdingCreditRealizedPct','Withholding credit realized in period (decimal)',{note:'0 = conservative timing drag; 1 = credit offsets current cash tax, limited to gross tax.'}]])}</div>`,'Tax classification and actual payment timing require independent confirmation.')}</div>${panel('Collateral realization assumptions',`<div class="fields">${fields('equipmentDeal',[['assetMarketValueNew','Total initial appraised market value'],['forcedSaleValuePct','Forced-sale factor (decimal)'],['annualAssetDepreciationRate','Annual reducing-balance depreciation'],['realizationCostPct','Recovery cost factor'],['realizationFixedCost','Fixed recovery costs'],['liquidationDelayMonths','Realization delay (months)']])}</div>`,'Depreciation is a scenario assumption, not an appraisal forecast.')}</div><div id="scenario-inputs" class="institution-tab" hidden>${scenarioControls()}</div><div id="facility-inputs" class="institution-tab" hidden>${facilityControls()}</div>`;}
function dealResults(){const r=evaluateScenario(w,w.ui.selectedScenario);return `<div class="institution-alerts">${r.flags.map(f=>`<span class="pill ${f.includes('ceiling')||f.includes('deficit')?'red':'amber'}">${h(f)}</span>`).join('')}</div><section class="card padded"><div class="detail-summary"><div><h2>Decision matrix</h2><p class="card-subtitle">Requested · proposed cap · downside, calculated from your inputs</p></div><button class="btn" data-inst-action="matrix-export">Export comparison CSV</button></div>${decisionMatrix()}</section><div class="detail-grid" style="margin-top:20px">${panel('Debt & realizable collateral',`<label>Chart scenario<select data-inst="ui.selectedScenario">${Object.keys(w.scenarios).map(k=>`<option value="${k}" ${w.ui.selectedScenario===k?'selected':''}>${h(w.scenarios[k].name)}</option>`).join('')}</select></label>${collateralChart(r)}<div class="legend"><span><i style="background:#16765b"></i>Outstanding principal</span><span><i style="background:#c99936"></i>Net forced-sale recovery</span></div><p class="evidence">${r.collateral.filter(p=>p.negativeEquityGap>0).length} monthly observations show a recovery gap. Inception and liquidation delays included.</p><button class="btn" data-inst-action="schedule-export">Export repayment & recovery</button><details><summary>Exact monthly schedule</summary>${scheduleTable(r)}</details>`)}${panel('Monthly cash bridge',cashBridge(r),'Click highlighted figures in the matrix to audit the calculation.')}</div><section class="card padded"><h2>Reverse stress & debt sizing</h2><p class="evidence">Indicative cap under ${h(w.scenarios.PROPOSED_CAP.name)}: <strong>${rp(indicativeDebtCap(w))}</strong>, constrained by Year-1 DSCR ${ratio(w.policy.minimumDSCR)} and total asset cost. Group ceiling, collateral, liquidity and qualitative evidence may require a lower limit.</p><div class="sensitivity institution-sensitivity">${[.4,.5,.6,.7,.8,.9,1].map(u=>{const clone=structuredClone(w);clone.scenarios.CUSTOM.utilizationPct=u;const x=evaluateScenario(clone,'CUSTOM');return `<div class="${x.year1PostShockDSCR!==null&&x.year1PostShockDSCR<w.policy.minimumDSCR?'risk-cell':''}"><small>${percent(u)} utilization</small><strong>${ratio(x.year1PostShockDSCR)}</strong></div>`;}).join('')}</div></section>`;}
function collateralChart(r){const points=r.collateral,W=600,H=220,max=Math.max(...points.flatMap(p=>[p.outstandingDebt,p.netForcedSaleValue]),1),x=m=>48+m/w.equipmentDeal.tenorMonths*528,y=v=>180-v/max*150,line=key=>points.map((p,i)=>(i?'L':'M')+x(p.month).toFixed(2)+','+y(p[key]).toFixed(2)).join(' ');return `<svg viewBox="0 0 ${W} ${H}" class="chart" role="img" aria-label="Outstanding principal and net forced-sale recovery over loan months">${[0,.5,1].map(a=>`<line x1="48" y1="${y(max*a)}" x2="580" y2="${y(max*a)}" stroke="#e7ecea"/><text x="0" y="${y(max*a)+4}">${fmt(max*a/1e9,1)}bn</text>`).join('')}<path d="${line('outstandingDebt')}" fill="none" stroke="#16765b" stroke-width="3"/><path d="${line('netForcedSaleValue')}" fill="none" stroke="#c99936" stroke-width="3"/>${[0,Math.round(w.equipmentDeal.tenorMonths/2),w.equipmentDeal.tenorMonths].map(m=>`<text x="${x(m)}" y="204" text-anchor="middle">Month ${m}</text>`).join('')}</svg>`;}
function scheduleTable(r){return `<div class="table-scroll"><table class="schedule-table"><thead><tr>${['Month','Principal','Interest','Payment','Balance','Net FSV','Recovery gap'].map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${r.schedule.map((s,i)=>`<tr><td>${s.month}</td><td>${fmt(s.principalPayment)}</td><td>${fmt(s.interestPayment)}</td><td>${fmt(s.totalInstallment)}</td><td>${fmt(s.endingBalance)}</td><td>${fmt(r.collateral[i+1].netForcedSaleValue)}</td><td class="${r.collateral[i+1].negativeEquityGap>0?'negative':''}">${fmt(r.collateral[i+1].negativeEquityGap)}</td></tr>`).join('')}</tbody></table></div>`;}
function cashBridge(r){const b=r.bridge;return `<div class="bridge-list">${[['Gross billed revenue',b.grossRevenue],['PPh 23 withheld',-b.pph23WithholdingDeduction],['Contractor fuel',-b.fuelCost],['Operators',-b.operatorCost],['Allocated overhead',-b.allocatedOverhead],['Maintenance capex reserve',-b.maintenanceReserve],['Gross tax proxy',-b.grossCashTax],['Tax credit realized',b.withholdingCreditRealized],['Monthly CFADS',b.monthlyCFADS]].map(([label,v],i)=>`<div class="ratio-row ${i===8?'bridge-total':''}"><span>${label}</span><strong class="${v<0?'negative':''}">${rp(v)}</strong></div>`).join('')}</div><p class="evidence">Maintenance reserve is deducted after EBITDA. PPh 23 credit realization is an explicit timing assumption. Negative CFADS is preserved.</p>`;}
function scenarioControls(){return `<div class="scenario-editor">${Object.entries(w.scenarios).map(([k,s])=>panel(h(s.name),`<div class="fields">${fields(`scenarios.${k}`,[['utilizationPct','Utilization (decimal)'],['tariffAdjustmentPct','Tariff change (decimal)'],['fuelPriceShockPct','Fuel price change (decimal)'],['dsoShockDays','Incremental DSO delay (days)'],['interestShockBps','Interest increase (bps)'],['seasonalQ1Factor','Q1 repayment weight (decimal)',{note:'Months 1–3 of each loan year. Final balancing payment is disclosed in the schedule.'}],['standbyHoursPerUnitMonth','Idle standby hours / unit / month']],{schema:specs.scenario})}</div>`)).join('')}</div>`;}
function facilityControls(){return panel('Existing debt & revolving liquidity',`<p class="evidence">Enter current balances from verified facility schedules. Only confirmed undrawn KMK supports modeled liquidity. LC balances are assumed crystallized for interest; contingent limits are retained for review.</p><div class="table-scroll"><table class="input-table"><thead><tr>${['Creditor','Type','Limit','Outstanding','Monthly principal','Annual rate','Revolving','Confirmed availability','Lender exposure','Collateral allocated','Security description',''].map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${w.existingDebts.map((d,i)=>`<tr><td>${input(`existingDebts.${i}.creditorName`,'Creditor',{type:'text'})}</td><td>${input(`existingDebts.${i}.facilityType`,'Facility type',{select:['WORKING_CAPITAL_KMK','TERM_LOAN','LEASING','LC_SKBDN']})}</td>${['limitAmount','outstandingBalance','monthlyPrincipalRepayment','annualInterestRate'].map(k=>`<td>${input(`existingDebts.${i}.${k}`,k,{schema:specs.facility})}</td>`).join('')}${['isRevolving','availabilityConfirmed','atLendingInstitution'].map(k=>`<td>${input(`existingDebts.${i}.${k}`,k,{checkbox:true})}</td>`).join('')}<td>${input(`existingDebts.${i}.collateralValueAllocated`,'Allocated collateral',{schema:specs.facility})}</td><td>${input(`existingDebts.${i}.collateralDescription`,'Security description',{type:'text'})}</td><td><button class="text-button negative" data-inst-remove="existingDebts:${i}">Remove</button></td></tr>`).join('')}</tbody></table></div><button class="btn" data-inst-action="add-facility">Add existing facility</button>`);}
const bankCols={periodMonth:'Month',totalCreditMutation:'Gross credits',totalDebitMutation:'Debits',intercompanyCredits:'Intercompany credits',nonRevenueCredits:'Other non-sales credits',averageDailyBalance:'Average balance',endingBalance:'Ending balance',bouncedChecksCount:'Bounced checks',lowBalanceDays:'Low-balance days',circularTransactionCount:'Circular transactions'};
function reconView(){return header('Bank reconciliation','Match adjusted bank turnover to period-aligned declared revenue.')+`<div id="institution-results">${reconResults()}</div>${panel('Statement periods',`<div class="fields">${input('bankReconciliation.declaredAnnualRevenue','Declared revenue for comparison period')}${input('bankReconciliation.comparisonPeriod','Comparison period description',{type:'text'})}${input('bankReconciliation.annualizePartial','Annualize partial turnover',{checkbox:true,detail:'Explicit analyst assumption'})}</div><div class="actions" style="margin:20px 0"><button class="btn" data-inst-action="bank-template">CSV template</button><label class="btn">Import bank CSV<input type="file" id="bank-csv-file" accept=".csv" hidden></label><button class="btn" data-inst-action="add-month">Add month</button></div><div class="table-scroll"><table class="input-table"><thead><tr>${Object.values(bankCols).map(c=>`<th>${c}</th>`).join('')}<th></th></tr></thead><tbody>${w.bankReconciliation.statements.map((m,i)=>`<tr>${Object.entries(bankCols).map(([k,label])=>`<td>${input(`bankReconciliation.statements.${i}.${k}`,label,{type:k==='periodMonth'?'month':'number',schema:specs.bank})}</td>`).join('')}<td><button class="text-button negative" data-inst-remove="bank:${i}">Remove</button></td></tr>`).join('')}</tbody></table></div>`,'Amounts are IDR. Exclude intercompany transfers, borrowing receipts, and other non-sales inflows explicitly.')}`;}
function reconResults(){const r=evaluateBankStatementIntegrity(w.bankReconciliation,w.policy);return `<div class="metrics">${mini('Adjusted credits',rp(r.adjustedCredits))}${mini('Turnover / reported revenue',percent(r.ratio))}${mini('Rejected transactions',fmt(r.bouncedChecks))}${mini('Reported periods',r.periods??0)}</div><div class="banner ${r.flag!=='RECONCILED'?'amber':''}">${r.observations.map(h).join(' · ')}</div>${r.annualizedCredits!==null?`<p class="evidence">Annualized estimate: ${rp(r.annualizedCredits)}. Raw adjusted credits: ${rp(r.adjustedCredits)}.</p>`:''}`;}
function mini(label,value){return `<div class="metric"><div class="metric-title">${label}</div><div class="metric-value">${value}</div></div>`;}
const spreadLabels={revenue:'Revenue',cogs:'Cost of goods sold',operatingExpenses:'Operating expenses (ex D&A)',depreciationAmortization:'Depreciation & amortization',interestExpense:'Interest expense',taxExpense:'Accounting tax expense',operatingCashFlow:'Operating cash flow',currentAssets:'Current assets',accountsReceivable:'Accounts receivable',cashAndEquivalents:'Cash & equivalents',currentLiabilities:'Current liabilities',totalGrossDebt:'Total debt',totalAssets:'Total assets',totalLiabilities:'Total liabilities',equity:'Equity',cashTaxesPaid:'Cash taxes paid',increaseInNWC:'Increase in working capital',maintenanceCapex:'Maintenance capex',mandatoryDistributions:'Mandatory dividends / drawings',affiliateReceivableAdjustment:'Uncollectible affiliate receivables'};
function spreadView(){return header('Historical financial spreading','Three statements, normalization, and source quality in one review surface.')+`<div class="actions" style="margin-bottom:20px"><button class="btn" data-inst-action="add-year">Add annual period</button><button class="btn" data-inst-action="add-ytd">Add YTD period</button><button class="btn" data-inst-action="spread-template">Download Excel template</button><label class="btn">Import Excel / CSV<input type="file" id="spread-file" accept=".xlsx,.csv" hidden></label><button class="btn" data-inst-action="common-size">${w.ui.commonSize?'Show amounts':'Common-size analysis'}</button></div><div id="institution-results">${spreadResults()}</div>${panel('Statement inputs',`<p class="evidence">Blank = unavailable. Amounts are whole IDR for the covered period. YTD values are never automatically annualized.</p><div class="table-scroll"><table class="input-table spread-input"><thead><tr><th>Reported input</th>${w.financialSpreading.years.map((y,i)=>`<th>${h(y.fiscalYear)} ${h(y.periodType)} <button class="text-button negative" data-inst-remove="year:${i}">Remove</button></th>`).join('')}</tr></thead><tbody>${[['fiscalYear','Fiscal year'],['periodType','Period type'],['periodMonths','Months covered'],['sourceReference','Source / document reference'],['auditTier','Auditor category'],['auditOpinion','Audit opinion'],['auditQualityHaircutPct','Analyst EBITDA haircut (decimal)'],...Object.entries(spreadLabels)].map(([k,label])=>`<tr><th scope="row">${label}</th>${w.financialSpreading.years.map((y,i)=>`<td>${input(`financialSpreading.years.${i}.${k}`,`${label} ${y.fiscalYear} ${y.periodType}`,{schema:specs.spread,type:k==='sourceReference'?'text':'number',select:k==='periodType'?['ANNUAL','YTD']:k==='auditTier'?['BIG_4','TIER_2_AFFILIATED','LOCAL_KAP','IN_HOUSE_UNAUDITED']:k==='auditOpinion'?['WTP_UNQUALIFIED','WDP_QUALIFIED','DISCLAIMER_ADVERSE']:undefined})}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`)}${panel('Normalization adjustments',w.financialSpreading.years.map((y,i)=>`<div class="normalization-block"><h3>${y.fiscalYear} ${y.periodType}</h3><button class="btn" data-inst-haircut="${i}">Apply suggested audit sensitivity</button><p class="evidence">Signed adjustment: positive add-back, negative deduction. Explain evidence and keep reported earnings intact.</p>${y.normalizationAdjustments.map((a,j)=>`<div class="adjustment-row">${input(`financialSpreading.years.${i}.normalizationAdjustments.${j}.description`,'Adjustment rationale',{type:'text'})}${input(`financialSpreading.years.${i}.normalizationAdjustments.${j}.amount`,'Signed adjustment amount')}${input(`financialSpreading.years.${i}.normalizationAdjustments.${j}.enabled`,'Include adjustment',{checkbox:true})}<button class="text-button negative" data-inst-remove="adjustment:${i}:${j}">Remove</button></div>`).join('')}<button class="btn" data-inst-add-adjustment="${i}">Add normalization adjustment</button></div>`).join(''))}`;}
function spreadResults(){const results=w.financialSpreading.years.map(calculateSpread),rows=[['Gross profit','grossProfit'],['Operating profit (EBIT)','ebit'],['Reported EBITDA','ebitda'],['Net income','netIncome'],['Normalization total','normalizationTotal'],['Normalized EBITDA','normalizedEbitda'],['Audit scenario adjustment','haircutAmount'],['Adjusted EBITDA','adjustedEbitda'],['Normalized CFADS','normalizedCFADS'],['Net working capital','nwc'],['Adjusted tangible net worth','tangibleNetWorth'],['EBIT / interest','interestCoverage'],['CFO / EBIT','cashConversion'],['Debt / adjusted EBITDA','leverage'],['Balance difference','balanceDiff'],['Balance status','balanceStatus']];return panel('Calculated analysis',`<div class="table-scroll"><table class="decision-table"><thead><tr><th>Calculated metric</th>${w.financialSpreading.years.map(y=>`<th>${y.fiscalYear} ${y.periodType}<small>${y.periodMonths} months</small></th>`).join('')}</tr></thead><tbody>${rows.map(([label,k])=>`<tr><th scope="row">${label}</th>${results.map((r,i)=>{let v=['cashConversion','leverage','interestCoverage'].includes(k)?ratio(r[k]):k==='balanceStatus'?r[k]:w.ui.commonSize?percent(Number.isFinite(w.financialSpreading.years[i].revenue)&&w.financialSpreading.years[i].revenue>0&&Number.isFinite(r[k])?r[k]/w.financialSpreading.years[i].revenue:null):rp(r[k]);return `<td class="${k==='balanceStatus'&&r.balanceStatus!=='BALANCED'||k==='cashConversion'&&r[k]!==null&&r[k]<w.policy.cashConversionThreshold?'breach-cell':''}">${['normalizedCFADS','nwc','cashConversion','interestCoverage','adjustedEbitda'].includes(k)?`<button class="audit-value" data-inst-spread-audit="${i}:${k}">${v}</button>`:v}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>${w.ui.commonSize?'<p class="evidence">Calculated income / cash metrics shown as % of reported revenue. Balance inputs remain in original amounts; see the balance common-size table below.</p>':''}${w.ui.commonSize?`<div class="table-scroll"><table class="decision-table"><thead><tr><th>Balance metric / total assets</th>${w.financialSpreading.years.map(y=>`<th>${y.fiscalYear} ${y.periodType}</th>`).join('')}</tr></thead><tbody>${['currentAssets','accountsReceivable','cashAndEquivalents','currentLiabilities','totalGrossDebt','equity'].map(k=>`<tr><th>${spreadLabels[k]}</th>${w.financialSpreading.years.map(y=>`<td>${percent(y.totalAssets>0&&y[k]!==null?y[k]/y.totalAssets:null)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}<p class="evidence">Audit haircuts are analyst sensitivities, not mandated by OJK or proof of financial accuracy. Default templates suggest 0/5/10/20% by category; audit opinion never automatically verifies figures. Adverse/disclaimer opinions require substantive diligence.</p>`);}
function governanceView(){return header('Group & contract risk','Expose concentration, legal dependencies, and evidence gaps.')+`<div id="institution-results">${governanceResults()}</div><div class="detail-grid">${panel('Borrower profile',`<div class="fields">${fields('borrower',[['companyName','Company name',{type:'text'}],['businessType','Business type',{select:['MINING_CONTRACTOR','CIVIL_CONSTRUCTION','LOGISTICS','PLANTATION']}],['operatingSinceYear','Operating since year'],['slikStatus','Reported SLIK classification',{select:['COL_1_CURRENT','COL_2_SPECIAL_MENTION','COL_3_SUBSTANDARD','COL_4_DOUBTFUL','COL_5_LOSS']}],['rkabApprovalStatus','RKAB / relevant license evidence',{select:['APPROVED','PENDING','EXEMPT']}],['ownershipStructure','Ownership & sponsor',{textarea:true}],['slikNotes','SLIK evidence notes',{textarea:true}]])}</div>`)}${panel('Group exposure & guarantees',`<div class="fields">${fields('groupExposure',[['parentHoldingName','Parent holding',{type:'text'}],['ultimateBeneficialOwner','Beneficial owner',{type:'text'}],['totalGroupBankExposure','Existing group exposure at this lender',{schema:specs.group}],['allBankGroupExposure','Group exposure across all banks',{schema:specs.group}],['bankLegalLendingLimitBMPK','Analyst-entered lender group ceiling',{schema:specs.group}],['exposureScope','Exposure / ceiling source and scope',{textarea:true}],['guaranteeStructure','Guarantee structure',{select:['PERSONAL_GUARANTEE','CORPORATE_GUARANTEE','JOINT_SEVERAL','NONE']}],['crossDefaultClauseEnforceable','Cross-default legal review',{checkbox:true,detail:'Independent legal confirmation obtained'}]])}</div>`,'This is a ceiling screen, not a legal BMPK certification. Match exposure measurement to the approved institutional limit.')}</div><div class="detail-grid">${panel('Offtaker protection',`<div class="fields">${fields('offtakerContract',[['offtakerName','Offtaker name',{type:'text'}],['tierClassification','Counterparty category',{select:['TIER_1_CONCESSIONAIRE','TIER_2_MID_MINER','SUB_CONTRACTOR']}],['remainingContractMonths','Contract months remaining',{schema:specs.contract}],['hasGuaranteedMinimumHours','Minimum-hours clause',{checkbox:true}],['guaranteedHoursPerUnitMonth','Guaranteed hours / unit / month',{schema:specs.contract}],['standbyHourlyRate','Standby hourly rate (IDR)',{schema:specs.contract}],['hasEarlyTerminationPenalty','Termination compensation',{checkbox:true}],['contractEvidenceVerified','Contract evidence verified',{checkbox:true}]])}</div>`,'Standby cash only enters the scenario when protections are verified and idle standby hours are explicitly modeled.')}${panel('Qualitative overlay',`<div class="fields">${fields('qualitativeScorecard',[['managementExperienceScore','Management & sponsor (1–5)'],['offtakerCreditworthinessScore','Offtaker credit quality (1–5)'],['contractTenorVsLoanTenorScore','Contract-tenor quality (1–5)'],['regulatoryComplianceScore','Regulatory evidence (1–5)'],['equipmentMarketabilityScore','Equipment liquidity (1–5)'],['evidenceNotes','Evidence and score rationale',{textarea:true}]])}</div>`,'Weights: sponsor 25%; off-taker / contract 35%; regulatory 20%; asset 20%. Grade is an uncalibrated analyst overlay.')}</div>${panel('Screening policy',`<div class="fields">${fields('policy',[['minimumDSCR','Minimum DSCR'],['maximumLeverage','Maximum debt / EBITDA'],['minimumBankRatio','Minimum turnover / revenue'],['maximumBankRatio','Maximum turnover / revenue'],['cashConversionThreshold','Minimum CFO / EBIT']])}</div>`)}${panel('Local change history',`<div class="table-scroll"><table><thead><tr><th>UTC timestamp</th><th>Change</th></tr></thead><tbody>${w.auditLog.slice(-12).reverse().map(a=>`<tr><td>${h(a.at)}</td><td>${h(a.action)}</td></tr>`).join('')||'<tr><td colspan="2">No saved edits yet.</td></tr>'}</tbody></table></div><p class="evidence">Browser-local diagnostic history, editable with the workspace. It is not an immutable institutional audit trail.</p>`)}`;}
function governanceResults(){const r=evaluateScenario(w,'PROPOSED_CAP'),score=qualitativeScore(w.qualitativeScorecard);return `<div class="metrics">${mini('Proposed group ceiling use',percent(r.groupBMPKUtilization))}${mini('Uncalibrated overlay grade',score.grade+' · '+fmt(score.score,2)+'/5')}${mini('Contract / loan tenor',w.offtakerContract.remainingContractMonths+' / '+w.equipmentDeal.tenorMonths+' mo')}${mini('Indicative cash-flow cap',rp(indicativeDebtCap(w)))}</div>${r.ceilingBreach?'<div class="banner breach-banner">CRITICAL: Proposed exposure exceeds the entered lender group ceiling.</div>':''}<div class="institution-alerts">${r.flags.map(f=>`<span class="pill amber">${h(f)}</span>`).join('')}</div><p class="evidence">All-bank group exposure ${rp(w.groupExposure.allBankGroupExposure)} is shown separately from this lender’s exposure. Legal limits, connected parties, off-balance exposures, guarantees, and capital definitions require compliance review.</p>`;}
function proposalView(){return header('Committee proposal','Generate a populated Nota Analisis draft from the current evidence.')+`<div class="actions" style="margin-bottom:20px"><button class="btn primary" data-inst-action="proposal-print">Print / Save PDF</button><button class="btn" data-inst-action="proposal-docx">Export editable DOCX</button><button class="btn" data-inst-action="proposal-html">Export HTML</button></div><div class="detail-grid proposal-grid">${panel('Analyst recommendation',`<div class="fields">${fields('memo',[['analyst','Analyst name',{type:'text'}],['recommendation','Recommendation',{select:['Further diligence','Support with conditions','Restructure / reduce limit','Decline']}],['rationale','Credit rationale',{textarea:true}],['conditions','Conditions precedent & mitigants',{textarea:true}],['exceptions','Policy exceptions and review authority',{textarea:true}],['reviewDate','Next review date',{type:'date'}]])}</div><p class="evidence">Drafts autosave. No score or scenario automatically approves the facility.</p>`)}<article class="memo institutional-proposal" id="institution-results">${proposalHTML()}</article></div>`;}
function proposalHTML(){const r=evaluateScenario(w,'PROPOSED_CAP'),recon=evaluateBankStatementIntegrity(w.bankReconciliation,w.policy),score=qualitativeScore(w.qualitativeScorecard);return `<div class="memo-header"><span class="pill gray">Draft · independent committee review</span><h1>NOTA ANALISIS PEMBIAYAAN</h1><p>${h(w.borrower.companyName)} · ${h(w.borrower.businessType)}<br>Parent: ${h(w.groupExposure.parentHoldingName)}<br>SLIK: ${h(w.borrower.slikStatus)} · Source: ${h(w.source)}<br>Analyst: ${h(w.memo.analyst||'Not assigned')} · Review date: ${h(w.memo.reviewDate||'Not set')}</p></div><h2>1. Facility term sheet</h2><div class="table-scroll"><table><tbody>${[['Purpose','Equipment acquisition'],['Requested / proposed',rp(evaluateScenario(w,'REQUESTED').amount)+' / '+rp(r.amount)],['Proposed equity',rp(r.equityContribution)],['Price / tenor',percent(w.equipmentDeal.annualInterestRate)+' / '+w.equipmentDeal.tenorMonths+' months'],['Amortization',w.equipmentDeal.repaymentStructure+'; '+w.equipmentDeal.gracePeriodMonths+' grace months'],['Security','Equipment charge / guarantees subject to legal perfection'],['Ownership',w.borrower.ownershipStructure],['Group / ceiling use',rp(r.groupExposure)+' / '+percent(r.groupBMPKUtilization)]].map(([k,v])=>`<tr><th>${h(k)}</th><td>${h(v)}</td></tr>`).join('')}</tbody></table></div><h2>2. Historical financial summary</h2><div class="table-scroll"><table><thead><tr><th>Period</th><th>Revenue</th><th>EBITDA</th><th>Normalized CFADS</th><th>Audit source</th></tr></thead><tbody>${w.financialSpreading.years.map(y=>{const c=calculateSpread(y);return `<tr><td>${y.fiscalYear} ${y.periodType} (${y.periodMonths} months)</td><td>${rp(y.revenue)}</td><td>${rp(c.ebitda)}</td><td>${rp(c.normalizedCFADS)}</td><td>${h(y.auditTier)} / ${h(y.auditOpinion)}</td></tr>`;}).join('')}</tbody></table></div><p>Bank turnover / declared revenue: ${percent(recon.ratio)}. ${recon.observations.map(h).join('; ')}.</p><h2>3. Repayment & sensitivities</h2>${decisionMatrix()}<p>PPh 23 applied at ${percent(w.equipmentDeal.pph23WithholdingRate)} with ${percent(w.equipmentDeal.withholdingCreditRealizedPct)} credit realized in-period. Maintenance capex remains a separate cash deduction. DSO uses a 360-day convention and gross invoices.</p><h2>4. Risk register & recommendation</h2><p>Analyst recommendation: <strong>${h(w.memo.recommendation)}</strong><br>Uncalibrated qualitative grade: ${score.grade} (${fmt(score.score,2)}/5).</p><ul>${r.flags.map(f=>`<li>${h(f)}. Obtain evidence and a specific mitigant before disposition.</li>`).join('')||'<li>Screening limits met; independent diligence remains required.</li>'}</ul><p style="white-space:pre-wrap">${h(w.memo.rationale||'Credit rationale not yet recorded.')}</p><h2>5. Conditions & policy exceptions</h2><p style="white-space:pre-wrap">${h(w.memo.conditions||'Confirm equity funding, security perfection, insurance, contract receivable assignments, liquidity support, and facility-specific covenants before drawdown.')}</p><p>Suggested screening covenants for review: minimum DSCR ${ratio(w.policy.minimumDSCR)}; maximum debt / EBITDA ${ratio(w.policy.maximumLeverage)}. Final legal definitions and monitoring dates require agreement.</p><p style="white-space:pre-wrap">${h(w.memo.exceptions||'Policy exception authority and rationale not yet recorded.')}</p><p class="evidence">Version ${VERSION} · ${h(w.lastSaved||'Unsaved illustrative case')} · Current calculated inputs; no credit approval or legal certification. Keep borrower and group-level cash-flow scope consistent.</p>`;}
function error(message){const box=$('#institution-error');if(box)box.innerHTML=`<div class="input-error">${h(message)}</div>`;else hooks.toast(message);}
function updateResults(){const banner=$('#institution-ceiling');if(banner)banner.hidden=!evaluateScenario(w,'PROPOSED_CAP').ceilingBreach;const root=$('[data-institution-route]'),route=root?.dataset.institutionRoute,results=$('#institution-results');if(results)results.innerHTML=({deal:dealResults,recon:reconResults,spread:spreadResults,governance:governanceResults,proposal:proposalHTML}[route]||(()=>''))();}
function mutate(path,value){const next=structuredClone(w);setPath(next,path,value);try{validateWorkspace(next);for(const k of keys.concat('CUSTOM'))evaluateScenario(next,k);w=next;persist(path+' changed');$('#institution-error').innerHTML='';updateResults();}catch(err){error(err.message+'; the last valid model has been retained.');}}
function tableCSV(rows){const q=v=>'"'+String(v??'').replaceAll('"','""')+'"';return rows.map(r=>r.map(v=>{const s=String(v??'');return q(/^[=+@\t\r]/.test(s)||(/^\-/.test(s)&&!Number.isFinite(Number(s)))?"'"+s:s);} ).join(',')).join('\n');}
function rerender(){hooks.render();}
function bindEvents(){window.addEventListener('beforeunload',()=>{if(saveTimer&&!loadMessage)try{localStorage.setItem('credit-institution-v2',JSON.stringify(w));}catch{}});document.addEventListener('input',e=>{const t=e.target;if(!t.dataset.inst||t.type==='checkbox'||t.tagName==='SELECT')return;const path=t.dataset.inst,value=['number','range'].includes(t.type)?t.value.trim()===''?null:Number(t.value):t.value;mutate(path,value);});document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.inst&&(t.type==='checkbox'||t.tagName==='SELECT'))mutate(t.dataset.inst,t.type==='checkbox'?t.checked:t.value);if(t.id==='institution-file')await loadFile(t.files[0]);if(t.id==='bank-csv-file')await importBank(t.files[0]);if(t.id==='spread-file')await importSpreads(t.files[0]);});document.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;try{if(t.dataset.instHaircut){const i=Number(t.dataset.instHaircut),y=w.financialSpreading.years[i];mutate('financialSpreading.years.'+i+'.auditQualityHaircutPct',suggestedAuditHaircut(y.auditTier,y.auditOpinion));rerender();}if(t.dataset.instTab){for(const el of document.querySelectorAll('.institution-tab'))el.hidden=el.id!==t.dataset.instTab;for(const b of document.querySelectorAll('[data-inst-tab]'))b.classList.toggle('primary',b===t);}if(t.dataset.instAudit)showAudit(...t.dataset.instAudit.split(':'));if(t.dataset.instSpreadAudit)showSpreadAudit(...t.dataset.instSpreadAudit.split(':'));if(t.dataset.instRemove){const [kind,i,j]=t.dataset.instRemove.split(':');if(kind==='existingDebts')w.existingDebts.splice(Number(i),1);if(kind==='bank')w.bankReconciliation.statements.splice(Number(i),1);if(kind==='year')w.financialSpreading.years.splice(Number(i),1);if(kind==='adjustment')w.financialSpreading.years[Number(i)].normalizationAdjustments.splice(Number(j),1);persist('Removed '+kind);rerender();}if(t.dataset.instAddAdjustment){w.financialSpreading.years[Number(t.dataset.instAddAdjustment)].normalizationAdjustments.push({description:'New adjustment — provide evidence',amount:0,enabled:false});persist('Normalization adjustment added');rerender();}if(t.dataset.instAction)await action(t.dataset.instAction);}catch(err){error(err.message);}});}
async function action(a){if(a==='backup')return hooks.download('credit-institution-workspace.json',JSON.stringify({...w,portfolio:hooks.getPortfolio()},null,2),'application/json');if(a==='load')return $('#institution-file').click();if(a==='density'){w.ui.compact=!w.ui.compact;persist('Display density changed');return rerender();}if(a==='recover')return hooks.download('unreadable-institution-storage.json',localStorage.getItem('credit-institution-v2')||'{}','application/json');if(a==='add-facility'){w.existingDebts.push({id:crypto.randomUUID(),creditorName:'New creditor',facilityType:'TERM_LOAN',isRevolving:false,limitAmount:0,outstandingBalance:0,monthlyPrincipalRepayment:0,annualInterestRate:0,collateralDescription:'Unverified',collateralValueAllocated:0,availabilityConfirmed:false,atLendingInstitution:false});persist('Facility added');return rerender();}if(a==='add-month'){const last=w.bankReconciliation.statements.map(m=>m.periodMonth).sort().at(-1)||'2025-12',date=new Date(last+'-01T00:00:00Z');date.setUTCMonth(date.getUTCMonth()+1);const row={...defaultWorkspace().bankReconciliation.statements[0],periodMonth:date.toISOString().slice(0,7)};for(const k of Object.keys(specs.bank))row[k]=0;w.bankReconciliation.statements.push(row);persist('Bank period added');return rerender();}if(a==='add-year'||a==='add-ytd'){const year=Math.max(2024,...w.financialSpreading.years.map(y=>y.fiscalYear))+(a==='add-ytd'?0:1);if(w.financialSpreading.years.some(y=>y.fiscalYear===year&&y.periodType===(a==='add-ytd'?'YTD':'ANNUAL')))throw Error('This period already exists');const y={...defaultWorkspace().financialSpreading.years[0],fiscalYear:year,periodType:a==='add-ytd'?'YTD':'ANNUAL',periodMonths:a==='add-ytd'?6:12,sourceReference:'Source not entered',normalizationAdjustments:[]};for(const key of Object.keys(specs.spread))if(key!=='auditQualityHaircutPct')y[key]=null;w.financialSpreading.years.push(y);persist('Financial period added');return rerender();}if(a==='common-size'){w.ui.commonSize=!w.ui.commonSize;persist('Common-size display changed');return rerender();}if(a==='bank-template')return hooks.download('bank-statement-template.csv',tableCSV([Object.keys(bankCols),Object.keys(bankCols).map(k=>defaultWorkspace().bankReconciliation.statements[0][k])]),'text/csv');if(a==='spread-template')return excelTemplate();if(a==='schedule-export'){const r=evaluateScenario(w,w.ui.selectedScenario);return hooks.download('repayment-recovery-'+r.key+'.csv',tableCSV([['month','beginning_balance','principal','interest','installment','ending_balance','market_value','net_fsv','recovery_gap'],...r.schedule.map((s,i)=>[s.month,s.beginningBalance,s.principalPayment,s.interestPayment,s.totalInstallment,s.endingBalance,r.collateral[i+1].assetMarketValue,r.collateral[i+1].netForcedSaleValue,r.collateral[i+1].negativeEquityGap])]),'text/csv');}if(a==='matrix-export'){const rows=keys.map(k=>evaluateScenario(w,k));return hooks.download('credit-comparison.csv',tableCSV([['metric',...rows.map(r=>r.scenario.name)],...['amount','equityContribution','steadyStateDSCR','year1PostShockDSCR','annualDebtServiceYear1','workingCapitalDSODrag','netLiquidityHeadroom','groupBMPKUtilization'].map(k=>[k,...rows.map(r=>r[k])])]),'text/csv');}if(a==='proposal-print'){document.body.classList.add('print-institution');window.print();document.body.classList.remove('print-institution');return;}if(a==='proposal-html')return hooks.download('nota-analisis.html',`<!doctype html><html lang="en"><meta charset="utf-8"><title>Credit proposal</title><style>body{font:14px Arial;margin:40px auto;max-width:1000px;padding:20px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ddd;padding:8px;text-align:left}p{line-height:1.6}button{border:0;background:none;color:inherit}small{display:block}.breach-cell{background:#fff0ed}</style>${proposalHTML()}</html>`,'text/html');if(a==='proposal-docx')return exportDocx();}
async function loadFile(file){if(!file)return;try{if(file.size>10*1024*1024)throw Error('Workspace exceeds 10 MB');let raw=JSON.parse(await file.text());const validated=migrateWorkspace(raw);const portfolio=raw.portfolio?hooks.validatePortfolio(raw.portfolio):null;hooks.showModal('Review workspace restore',`<p class="subtitle">${h(validated.borrower.companyName)} · ${validated.existingDebts.length} facilities · ${validated.financialSpreading.years.length} periods. Restore replaces the institutional workspace${portfolio?' and portfolio':''}.</p><div class="actions" style="margin-top:20px"><button class="btn" data-inst-action="backup">Backup current workspace</button><button class="btn primary" id="confirm-institution-import">Restore validated workspace</button></div>`);$('#confirm-institution-import').onclick=()=>{w=validated;if(portfolio)hooks.restorePortfolio(portfolio);loadMessage='';persist('Workspace restored');$('#modal').close();rerender();hooks.toast('Validated workspace restored');};}catch(err){error(err.message);}}
async function importBank(file){if(!file)return;try{if(file.size>5*1024*1024)throw Error('File exceeds 5 MB');const parsed=parseCSV(await file.text()),aliases={period:'periodMonth',bulan:'periodMonth',credit:'totalCreditMutation',kredit:'totalCreditMutation',debit:'totalDebitMutation',debet:'totalDebitMutation',avgbalance:'averageDailyBalance',saldo_rata_rata:'averageDailyBalance',endbalance:'endingBalance',saldo_akhir:'endingBalance',bounced:'bouncedChecksCount',tolakan:'bouncedChecksCount'};for(const k of Object.keys(bankCols))aliases[k.toLowerCase()]=k;const rows=parsed.map((raw,i)=>{const r={};for(const [k,v] of Object.entries(raw)){if(aliases[k])r[aliases[k]]=v;}for(const k of Object.keys(specs.bank)){if(r[k]===undefined||r[k]==='')throw Error(`Bank row ${i+1}: ${k} required; provide zero when explicitly confirmed`);r[k]=Number(r[k]);}return r;});const next={...w.bankReconciliation,statements:rows};validateBank(next);hooks.showModal('Review bank import',`<p>${rows.length} valid months. Confirm the declared revenue covers the same period.</p><button class="btn primary" id="confirm-bank-import">Replace statement months</button>`);$('#confirm-bank-import').onclick=()=>{w.bankReconciliation=next;persist('Bank CSV imported');$('#modal').close();rerender();};}catch(err){error(err.message);}}
async function importSpreads(file){if(!file)return;try{if(file.size>5*1024*1024)throw Error('File exceeds 5 MB');let records;if(file.name.toLowerCase().endsWith('.csv'))records=parseCSV(await file.text());else{const X=await import('./vendor/xlsx.mjs');const workbook=X.read(await file.arrayBuffer(),{type:'array'});if(workbook.SheetNames.length>10)throw Error('Too many sheets');records=X.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]],{defval:null}).map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k.toLowerCase(),v])));}const rows=records.map((r,i)=>{const y={normalizationAdjustments:[]};for(const k of ['fiscalYear','periodType','periodMonths','sourceReference','auditTier','auditOpinion',...Object.keys(specs.spread)]){const v=r[k.toLowerCase()];if(typeof v==='boolean')throw Error('Boolean values are not valid financial amounts');if(['periodType','sourceReference','auditTier','auditOpinion'].includes(k))y[k]=String(v??'');else y[k]=v===null||v===undefined||v===''?null:Number(v);}if(y.fiscalYear===null)throw Error(`Row ${i+1}: fiscalYear required`);return y;});validateSpreads(rows);hooks.showModal('Review financial import',`<p>${rows.length} validated periods. This replaces the historical spread and normalization adjustments.</p><button class="btn primary" id="confirm-spread-import">Use imported statements</button>`);$('#confirm-spread-import').onclick=()=>{w.financialSpreading.years=rows;persist('Financial statements imported');$('#modal').close();rerender();};}catch(err){error(err.message);}}
async function excelTemplate(){const X=await import('./vendor/xlsx.mjs');const y=defaultWorkspace().financialSpreading.years;const rows=y.map(({normalizationAdjustments,...rest})=>rest);const book=X.utils.book_new();X.utils.book_append_sheet(book,X.utils.json_to_sheet(rows),'Financial statements');const bytes=X.write(book,{bookType:'xlsx',type:'array'});downloadBinary('financial-spread-template.xlsx',bytes,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}
function downloadBinary(name,data,type){const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function exportDocx(){const D=await import('./vendor/docx.mjs');const root=document.createElement('div');root.innerHTML=proposalHTML();const paragraphs=[];for(const node of root.children){if(node.tagName==='TABLE'||node.classList.contains('table-scroll')){const table=node.tagName==='TABLE'?node:node.querySelector('table');if(table){paragraphs.push(new D.Table({rows:[...table.rows].map(row=>new D.TableRow({children:[...row.cells].map(cell=>new D.TableCell({children:[new D.Paragraph({text:cell.textContent.replace(/\s+/g,' ').trim()})]}))}))}));continue;}}const text=node.textContent?.trim();if(text)paragraphs.push(new D.Paragraph({text,heading:node.tagName==='H2'?D.HeadingLevel.HEADING_2:undefined}));}const doc=new D.Document({creator:w.memo.analyst||'Credit Workbench',title:'Nota Analisis Pembiayaan',sections:[{children:paragraphs}]});const blob=await D.Packer.toBlob(doc);downloadBinary('nota-analisis-pembiayaan.docx',blob,'application/vnd.openxmlformats-officedocument.wordprocessingml.document');}
function showAudit(key,type){const r=evaluateScenario(w,key),b=r.bridge;let title='Calculation audit',formula='',rows=[];if(type==='cfads'){title='Projected CFADS';formula='Revenue − withholding − fuel − operators − overhead − maintenance capex − cash tax + realized withholding credit';rows=[['Gross revenue × 12',b.grossRevenue*12],['Withholding × 12',-b.pph23WithholdingDeduction*12],['Fuel × 12',-b.fuelCost*12],['Operator cost × 12',-b.operatorCost*12],['Overhead × 12',-b.allocatedOverhead*12],['Maintenance reserve × 12',-b.maintenanceReserve*12],['Gross tax proxy × 12',-b.grossCashTax*12],['Withholding credit realized × 12',b.withholdingCreditRealized*12],['Annual CFADS',b.annualizedCFADS]];}if(type==='service'){title='Year-1 global debt service';formula='New facility principal + interest in months 1–12 + modeled existing debt service';rows=[['New facility service',r.newFacilityDebtServiceYear1],['Existing facility service',r.existing.annualDebtService],['Global service',r.annualDebtServiceYear1]];}if(type==='dscr'||type==='year1'){title=type==='year1'?'Year-1 DSCR after DSO':'Steady-state DSCR';formula=type==='year1'?'(Annual CFADS − gross annual revenue × extra DSO / 360) / global debt service':'Annual CFADS / global debt service';rows=[['Annual CFADS',b.annualizedCFADS],['DSO cash drag',type==='year1'?-r.workingCapitalDSODrag:0],['Debt service',r.annualDebtServiceYear1],['DSCR result',type==='year1'?r.year1PostShockDSCR:r.steadyStateDSCR]];}if(type==='breakeven'){title='Break-even utilization';formula=`Solve annual CFADS(u) = ${w.policy.minimumDSCR} × year-1 global debt service, holding tariff, fuel, tax and repayment scenario constant`;rows=[['Global annual service',r.annualDebtServiceYear1],['Required CFADS',r.annualDebtServiceYear1*w.policy.minimumDSCR],['Utilization (decimal)',r.breakEven.value],['Numerical residual (IDR)',r.breakEven.residual]];}hooks.showModal(title,`<p class="audit-formula">${h(formula)}</p><table class="audit-table"><tbody>${rows.map(([k,v])=>`<tr><th>${h(k)}</th><td>${fmt(v,k.includes('DSCR')||k.includes('decimal')?4:2)}</td></tr>`).join('')}</tbody></table><p class="evidence">Scenario ${h(r.scenario.name)}. ${h(type==='breakeven'?r.breakEven.status:'Full precision used for decisions; formatting only at display.')}</p>`);}
function showSpreadAudit(index,key){const y=w.financialSpreading.years[Number(index)],c=calculateSpread(y),formulas={normalizedCFADS:'Adjusted EBITDA − cash taxes − increase in NWC − maintenance capex − mandatory distributions',nwc:'Current assets − current liabilities',interestCoverage:'Operating profit (EBIT) / interest expense',cashConversion:'Operating cash flow / EBIT',adjustedEbitda:'(Reported EBITDA + enabled normalization adjustments) × (1 − analyst haircut); deficits preserved'};hooks.showModal('Historical calculation audit',`<p class="audit-formula">${h(formulas[key])}</p><p>${y.fiscalYear} ${y.periodType} · Source ${h(y.sourceReference)}</p><table class="audit-table"><tbody>${[['Reported EBITDA',c.ebitda],['Normalization',c.normalizationTotal],['Adjusted EBITDA',c.adjustedEbitda],['Cash tax',y.cashTaxesPaid],['Increase NWC',y.increaseInNWC],['Maintenance capex',y.maintenanceCapex],['Distributions',y.mandatoryDistributions],['Current assets',y.currentAssets],['Current liabilities',y.currentLiabilities],['CFO',y.operatingCashFlow],['EBIT',c.ebit],['Interest expense',y.interestExpense],['Selected result',c[key]]].map(([k,v])=>`<tr><th>${k}</th><td>${fmt(v,2)}</td></tr>`).join('')}</tbody></table>`);}
